# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Timekeeping handoff round trip of the monolith checkpoint file" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:round_trip_service_token) { "service-#{SecureRandom.hex(24)}" }
  let(:round_trip_headers) do
    { "Authorization" => "Bearer #{round_trip_service_token}", "Content-Type" => "application/json" }
  end

  around do |example|
    with_timekeeping_env(Timekeeping::Environment::SERVICE_TOKEN => round_trip_service_token) { example.run }
  end

  # "Populated audits, idempotency receipts and operation receipts round-trip
  # between the two stores unchanged"
  # A row Timekeeping held before the load is not in the monolith's checkpoint,
  # so it must not survive into the export.
  it "replaces stale Timekeeping rows with the monolith checkpoint file and exports it back with equal rows and checksums" do
    stale = Entry.create!(id: 987_654, company_id: 424_242, user_id: 1, project_id: 2, work_date: "2026-03-02",
                          duration: 15.0, note: "Stale", bill_status: "unbilled", source: "manual", source_metadata: {})
    Timekeeping::Admission.fence!
    body = Rails.root.join("../spec/fixtures/files/timekeeping_handoff/monolith_checkpoint.json").read
    source = Timekeeping::Handoff::Checkpoint.from_json(body)

    put "/internal/v1/handoff/checkpoint", params: body, headers: round_trip_headers
    expect(response.status).to eq(200)
    get "/internal/v1/handoff/checkpoint", headers: round_trip_headers
    expect(response.status).to eq(200)
    exported = Timekeeping::Handoff::Checkpoint.from_json(response.body)

    %w[invoice_operations entry_audits idempotency_records].each do |table|
      expect(source.rows.fetch(table)).not_to be_empty, "the file holds no #{table} rows"
    end
    expect(exported.digest).to eq(source.digest)
    expect(Timekeeping::Handoff::Checkpoint.verify(exported)).to eq([])
    expect(Entry.exists?(stale.id)).to be(false)
  end
end
